// MODULE 1: URGENCY/TIMING SCORE CALCULATION
try {
  let urgencyScore = 0;
  let urgencyReasons = [];
  let maxScore = 100;

  const currentDate = new Date();
  const currentMonth = currentDate.getMonth() + 1;

  // 1. NEW HOMEOWNER STATUS SCORING
  let newHomeownerScore = 0;
  if ($json.days_since_purchase !== undefined && $json.days_since_purchase !== null) {
    const daysSincePurchase = parseInt($json.days_since_purchase);

    if (daysSincePurchase <= 90) {
      newHomeownerScore = 100;
      urgencyReasons.push("New homeowner (≤90 days): +100 points");
    } else if (daysSincePurchase <= 180) {
      newHomeownerScore = 70;
      urgencyReasons.push("Recent homeowner (91-180 days): +70 points");
    } else if (daysSincePurchase <= 365) {
      newHomeownerScore = 40;
      urgencyReasons.push("Moderate homeowner (181-365 days): +40 points");
    } else {
      newHomeownerScore = 20;
      urgencyReasons.push("Established homeowner (>365 days): +20 points");
    }
  } else {
    newHomeownerScore = 10;
    urgencyReasons.push("Unknown homeowner status: +10 points (default)");
  }

  // 2. SEASONAL TIMING SCORING
  let seasonalBonus = 0;
  const serviceType = 'landscaping'; // Default for now

  if (serviceType === 'landscaping') {
    if ([3, 4, 5].includes(currentMonth)) {
      seasonalBonus = 25;
      urgencyReasons.push("Spring peak season for landscaping: +25 points");
    } else if ([9, 10].includes(currentMonth)) {
      seasonalBonus = 15;
      urgencyReasons.push("Fall shoulder season for landscaping: +15 points");
    } else {
      seasonalBonus = 5;
      urgencyReasons.push("Off-season for landscaping: +5 points");
    }
  }

  // 3. RECENT PERMITS SCORING
  let permitScore = 0;
  if ($json.days_since_permit !== undefined && $json.days_since_permit !== null) {
    const daysSincePermit = parseInt($json.days_since_permit);

    if (daysSincePermit <= 30) {
      permitScore = 90;
      urgencyReasons.push("Recent permit (≤30 days): +90 points");
    } else if (daysSincePermit <= 90) {
      permitScore = 60;
      urgencyReasons.push("Moderate permit age (31-90 days): +60 points");
    } else if (daysSincePermit <= 180) {
      permitScore = 30;
      urgencyReasons.push("Older permit (91-180 days): +30 points");
    } else {
      permitScore = 0;
      urgencyReasons.push("Old permit (>180 days): +0 points");
    }
  } else {
    urgencyReasons.push("No permit data available: +0 points");
  }

  // 4. CODE VIOLATIONS SCORING
  let violationScore = 0;
  if ($json.days_since_violation !== undefined && $json.days_since_violation !== null) {
    const daysSinceViolation = parseInt($json.days_since_violation);

    if (daysSinceViolation <= 60) {
      violationScore = 85;
      urgencyReasons.push("Recent violation (≤60 days): +85 points");
    } else if (daysSinceViolation <= 180) {
      violationScore = 40;
      urgencyReasons.push("Moderate violation age (61-180 days): +40 points");
    } else {
      violationScore = 0;
      urgencyReasons.push("Old violation (>180 days): +0 points");
    }
  } else {
    urgencyReasons.push("No violation data available: +0 points");
  }

  // 5. CALCULATE FINAL TIMING SCORE
  urgencyScore = newHomeownerScore + seasonalBonus + permitScore + violationScore;
  urgencyScore = Math.min(urgencyScore, maxScore);
  urgencyScore = Math.max(urgencyScore, 0);

  urgencyReasons.push(`FINAL TIMING SCORE: ${urgencyScore}/100`);

  return [{
    json: {
      ...$json,
      urgency_score: urgencyScore,
      urgency_reasons: urgencyReasons,
      timing_breakdown: {
        new_homeowner_score: newHomeownerScore,
        seasonal_bonus: seasonalBonus,
        permit_score: permitScore,
        violation_score: violationScore
      },
      current_month: currentMonth
    }
  }];

} catch (error) {
  return [{
    json: {
      ...$json,
      urgency_score: 20,
      urgency_reasons: ["Error in timing calculation: +20 points (default)"],
      error: error.message
    }
  }];
}
